import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Bare Metal Cloud Password Change and Reset Guide","description":"","frontmatter":{"title":"Bare Metal Cloud Password Change and Reset Guide"},"headers":[],"relativePath":"operations-knowledge-base/baremetal/bare-metal-cloud-password-change-and-reset-guide.md","filePath":"operations-knowledge-base/baremetal/bare-metal-cloud-password-change-and-reset-guide.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/baremetal/bare-metal-cloud-password-change-and-reset-guide.md"};function n(i,e,l,h,d,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document describes how to change and reset passwords for Bare Metal Cloud servers. It applies to both Linux and Windows operating systems and helps users quickly complete password-related operations when they need to change or reset their server password.</p><p><strong>Applicable Product:</strong> Bare Metal Cloud</p><hr><h2 id="_1-difference-between-changing-and-resetting-a-password" tabindex="-1">1. Difference Between Changing and Resetting a Password <a class="header-anchor" href="#_1-difference-between-changing-and-resetting-a-password" aria-label="Permalink to &quot;1. Difference Between Changing and Resetting a Password&quot;">​</a></h2><p>Before proceeding, please confirm which operation you need.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Operation</td><td>Applicable Scenario</td></tr><tr><td><strong>Change Password</strong></td><td>You can log in to the server normally and want to change your current login password.</td></tr><tr><td><strong>Reset Password</strong></td><td>You have forgotten the server password and cannot log in. A new login password needs to be generated.</td></tr></tbody></table><h2 id="_2-changing-the-system-password" tabindex="-1">2. Changing the System Password <a class="header-anchor" href="#_2-changing-the-system-password" aria-label="Permalink to &quot;2. Changing the System Password&quot;">​</a></h2><p>If you can still log in to the server, it is recommended to change the password directly within the operating system.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><p>Applicable when:</p><ul><li>You can log in to the server via SSH.</li><li>You can access the server through VNC.</li></ul><p>After changing the password, please log in again using the new password to verify that it has taken effect.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Applicable when:</p><ul><li>You can log in to the server via Remote Desktop (RDP).</li><li>You can access the server through VNC.</li></ul><p>After changing the password, please log in again using the new password to verify that it has taken effect.</p><p><strong>Note:</strong> The password change procedure may vary depending on the operating system version. Please follow the instructions for your specific operating system.</p><hr><h2 id="_3-resetting-the-password-through-the-control-panel" tabindex="-1">3. Resetting the Password Through the Control Panel <a class="header-anchor" href="#_3-resetting-the-password-through-the-control-panel" aria-label="Permalink to &quot;3. Resetting the Password Through the Control Panel&quot;">​</a></h2><p>If you have forgotten your server password and cannot log in, you can generate a new password using the <strong>Reset Password</strong> feature in the Bare Metal Cloud Control Panel.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Log in to the Raksmart Client Portal.</li><li>Navigate to <strong>Product Management</strong> → <strong>Bare Metal Cloud</strong>.</li><li>Select the server you want to manage.</li><li>Go to the <strong>Management</strong> page.</li><li>Click <strong>Reset Password</strong>.</li><li>The system will automatically generate a new random password.</li><li>If you would like a different password, click <strong>Regenerate</strong> to generate another random password, or enter your own custom password.</li><li>Once confirmed, click <strong>Copy</strong> to save the new password.</li></ol><h2 id="after-resetting" tabindex="-1">After Resetting <a class="header-anchor" href="#after-resetting" aria-label="Permalink to &quot;After Resetting&quot;">​</a></h2><p>Once the new password has been generated, you can use it to log in to your server immediately.</p><p>Supported login methods:</p><ul><li><strong>Linux:</strong> SSH or VNC</li><li><strong>Windows:</strong> Remote Desktop (RDP) or VNC</li></ul><p><strong>Note:</strong></p><p>The new password takes effect immediately after the reset. No server reboot is required.</p><hr><h2 id="_4-when-should-you-use-vnc" tabindex="-1">4. When Should You Use VNC? <a class="header-anchor" href="#_4-when-should-you-use-vnc" aria-label="Permalink to &quot;4. When Should You Use VNC?&quot;">​</a></h2><p>It is recommended to use VNC to access your server in the following situations:</p><ul><li>SSH connection is unavailable.</li><li>RDP connection is unavailable.</li><li>You cannot confirm whether the server has started successfully.</li><li>Network configuration issues prevent remote access.</li><li>You need to view the server boot process.</li></ul><p><strong>Note:</strong></p><p>VNC provides direct console access to the server. Even if the network connection is unavailable, you can usually still access and manage the system through VNC.</p><p>For detailed instructions, please refer to <strong>Bare Metal Cloud VNC Console User Guide</strong>.</p><hr><h2 id="_5-password-security-recommendations" tabindex="-1">5. Password Security Recommendations <a class="header-anchor" href="#_5-password-security-recommendations" aria-label="Permalink to &quot;5. Password Security Recommendations&quot;">​</a></h2><p>To improve server security, we recommend the following:</p><ul><li>Use a password with at least 12 characters.</li><li>Include uppercase letters, lowercase letters, numbers, and special characters.</li><li>Avoid using easily guessed information such as birthdays or phone numbers.</li><li>Change your password regularly.</li><li>Keep your password secure and do not share it with others.</li></ul><hr><h2 id="_6-frequently-asked-questions" tabindex="-1">6. Frequently Asked Questions <a class="header-anchor" href="#_6-frequently-asked-questions" aria-label="Permalink to &quot;6. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-will-changing-or-resetting-the-password-affect-my-server-data" tabindex="-1">Q1: Will changing or resetting the password affect my server data? <a class="header-anchor" href="#q1-will-changing-or-resetting-the-password-affect-my-server-data" aria-label="Permalink to &quot;Q1: Will changing or resetting the password affect my server data?&quot;">​</a></h3><p>No.</p><p>Changing or resetting the password only updates the login credentials. It does not affect the operating system, applications, or any data stored on the server.</p><hr><h3 id="q2-do-i-need-to-reboot-the-server-after-resetting-the-password" tabindex="-1">Q2: Do I need to reboot the server after resetting the password? <a class="header-anchor" href="#q2-do-i-need-to-reboot-the-server-after-resetting-the-password" aria-label="Permalink to &quot;Q2: Do I need to reboot the server after resetting the password?&quot;">​</a></h3><p>No.</p><p>The new password becomes effective immediately after it is reset through the control panel. A server reboot is not required.</p><hr><h3 id="q3-why-can-t-i-log-in-after-resetting-the-password" tabindex="-1">Q3: Why can&#39;t I log in after resetting the password? <a class="header-anchor" href="#q3-why-can-t-i-log-in-after-resetting-the-password" aria-label="Permalink to &quot;Q3: Why can&#39;t I log in after resetting the password?&quot;">​</a></h3><p>Please check the following:</p><ul><li>Make sure you are using the most recently generated password.</li><li>Verify that you are using the correct username (for example, <strong>root</strong> for Linux or <strong>Administrator</strong> for Windows).</li><li>Confirm that you are connecting to the correct IP address and port.</li><li>Ensure that the SSH or RDP service is running properly.</li><li>Check whether the Security Group or system firewall is blocking the connection.</li></ul><p>If you still cannot log in, try accessing the server through the VNC console for further troubleshooting.</p><hr><h3 id="q4-can-i-set-my-own-password-when-resetting-it" tabindex="-1">Q4: Can I set my own password when resetting it? <a class="header-anchor" href="#q4-can-i-set-my-own-password-when-resetting-it" aria-label="Permalink to &quot;Q4: Can I set my own password when resetting it?&quot;">​</a></h3><p>Yes.</p><p>The Reset Password feature allows you to either use a randomly generated password or enter your own custom password before completing the reset.</p><hr><h3 id="q5-will-resetting-the-password-reboot-my-server" tabindex="-1">Q5: Will resetting the password reboot my server? <a class="header-anchor" href="#q5-will-resetting-the-password-reboot-my-server" aria-label="Permalink to &quot;Q5: Will resetting the password reboot my server?&quot;">​</a></h3><p>No.</p><p>Resetting the password through the control panel does not affect the server&#39;s current running status and will not automatically reboot the server.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ It is recommended to change the default password immediately after your first login.</p><p>⚠️ Before closing the Reset Password window, make sure you have copied or recorded the new password.</p><p>⚠️ If your server uses automated management or deployment tools, remember to update the saved password in those tools to avoid authentication failures.</p><p>⚠️ If you are unable to log in with the new password for an extended period, please use the VNC console to verify the server status first.</p>',68)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
